contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint extraDeposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= extraDeposit);

        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        balBefore = address(c).balance;
        countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(address(c).balance == balBefore && c.depositsCount() == countBefore);
    }

    receive() external payable {}
}

